const handles=Array.from({length:3},()=>({x:0,y:0,vx:0,vy:0}));let grabbed=-1,hovered=-1,press=[0,0],distance=0,flip=0,flipTarget=0,flips=0,lastRibbonNote=0,lastPitch=-1;
