const scene={init(){handles.forEach((h,k)=>{[h.x,h.y]=home(k);});document.querySelector('#flip-ribbon').addEventListener('click',()=>{flipRibbon();requestDraw();});},reset(){grabbed=-1;},tap(){press=[state.x*1000,state.y*700];distance=0;grabbed=handleAt();hovered=grabbed;if(grabbed>=0){const h=handles[grabbed];h.vx=h.vy=0;h.x=press[0];h.y=press[1];feedback(`第 ${grabbed+1} 條緞帶 · 拖曳白圈，左低右高`);}},move(){hovered=handleAt();if(state.held){distance=Math.max(distance,Math.hypot(state.x*1000-press[0],state.y*700-press[1]));if(grabbed>=0){const h=handles[grabbed],x=state.x*1000,y=state.y*700;h.vx=clamp((x-h.x)*12,-500,500);h.vy=clamp((y-h.y)*12,-500,500);h.x=x;h.y=y;const midi=ribbonNote();feedback(`第 ${grabbed+1} 條 · ${noteName(midi)} · 放開讓緞帶慢慢回彈`);}}},release(){if(distance<12)flipRibbon();else if(grabbed>=0)feedback(`第 ${grabbed+1} 條放開了 · 端點帶著慣性回彈`);grabbed=-1;},cancel(){grabbed=-1;},leave(){hovered=-1;},inspect(){return{handles:handles.map(h=>({...h})),grabbed,hovered,flips,flip,flipTarget,phrase:state.phraseMidi};},update(dt){flip=mix(flip,flipTarget,1-Math.exp(-dt*4.5));for(let k=0;k<3;k++){if(k===grabbed)continue;const h=handles[k],[x,y]=home(k);h.vx+=(x-h.x)*dt*22;h.vy+=(y-h.y)*dt*22;h.vx*=Math.exp(-dt*4);h.vy*=Math.exp(-dt*4);h.x=clamp(h.x+h.vx*dt,60,940);h.y=clamp(h.y+h.vy*dt,90,580);}},draw(){circle(500,355,218,null,INK+'12');ctx.setLineDash([2,12]);circle(500,355,268,null,INK+'18');ctx.setLineDash([]);const turn=flipTarget-flip;for(let k=2;k>=0;k--){let pts=ribbonPoints(k);line(pts.map(([x,y])=>[x+4,y+10]),INK+'0d',23);line(pts,C[k],18);line(pts.map(([x,y])=>[x-2,y-4]),'#fff5df65',3);}handles.forEach((h,k)=>{const x=h.x,y=h.y;circle(x,y,18,C[k]);ctx.lineWidth=k===grabbed||k===hovered?5:3;circle(x,y,24,null,'#fff7e9');text(String(k+1),x,y+5,13,'#fff7e9');});if(grabbed>=0)dashed([[press[0],press[1]],[state.x*1000,state.y*700]],C[grabbed]+'90');text('抓住白圈端點拖曳 · 點一下，翻一圈',500,640,17,INK+'a0');}};

